    static PointerDef D(string n,int t,int b,int f,string c,int s,string ctx,bool u,string raw,string fmt){
      var p=new PointerDef(); p.Name=n; p.Type=t; p.BaseOffset=b; p.FieldOffset=f; p.Stride=s; p.Context=ctx; p.Unicode=u; p.Raw=raw; p.Format=fmt; p.Chain=ParseChain(c); p.Category=Categorize(n,ctx); return p;
    }
    static int[] ParseChain(string s){ if(string.IsNullOrEmpty(s)) return new int[0]; var parts=s.Split(','); var r=new int[parts.Length]; for(int i=0;i<parts.Length;i++) r[i]=Convert.ToInt32(parts[i],16); return r; }
    static string Categorize(string n,string ctx){
      if(ctx=="screen"||ctx=="chartarget"||ctx=="charaddress"||ctx=="selected") return "Pointer";
      if(n=="CharAddress"||n=="CharTarget"||n=="NPCAddress"||n=="NPCTarget"||n=="NPCTargetOth"||n=="SelectedChar"||n=="SelectedTarget"||n=="ScreenType") return "Pointer";
      if(ctx=="global"){
        if(n.StartsWith("Time")||n.StartsWith("Day")||n=="ClassName"||n=="Year"||n=="Classess"||n=="SaveName"||n=="PlayTime"||n.StartsWith("Club1")||n.StartsWith("Club2")||n.StartsWith("Club3")||n.StartsWith("Club4")||n.StartsWith("Club5")||n.StartsWith("Club6")||n.StartsWith("Club7")||n.StartsWith("Club8")) return "Class";
        return "Config";
      }
      if(n.StartsWith("Mood")) return "Mood";
      if(n.StartsWith("Love")||n.StartsWith("Like")||n.StartsWith("Dislike")||n.StartsWith("Hate")||n.StartsWith("Level")||n=="compatible"||n=="Lover"||n=="Friend"||n=="Sexual") return "Relation";
      if(n.StartsWith("Date")||n.StartsWith("Meet")||n.StartsWith("Lewd")) return "Promise";
      if(n=="Status"||n=="Action"||n=="ReffTo"||n=="Location"||n=="Response"||n=="MoodAction"||n=="IntructionWait"||n=="IntructionTime"||n=="FireAction"||n=="RandomAction"||n=="PCInteract"||n=="NPCInteract"||n.StartsWith("NA")) return "Activity";
      return "Character";
    }
